//! `cargo xtask icon`: draw both app icons and write them in every size the platforms want.
//!
//! The artwork is original and drawn in code, in `xtask/src/art/`: an engraved animal in the
//! manner of a wood engraving, the way the Craft apps' icons are made, in exactly three colours —
//! black ink line work, a cream (paper) figure and the app's colour as the field. Nothing is
//! traced, copied or generated by an image model, and nothing comes from another product's icon.
//!
//! - **ScreenGrabCraft**, the capture service: a peregrine falcon framed by the four corner
//!   brackets of a capture selection, on deep teal.
//! - **ScreenGrabCraft Editor**: a barn owl with a pencil in its beak, on indigo.
//!
//! Each drawing is set in the Craft tile: a 512-unit rounded square (`rx` 112) in the app colour,
//! the figure clipped to a rounded rectangle 6 units in (`rx` 106) so a thin band of the colour
//! wraps it. The macOS renders sit on Apple's 824/1024 grid, and the 16–64 px renders show the
//! figure 22 units closer on each side so it still reads.
//!
//! Output (all listed in ATTRIBUTION.md), for each icon's `<stem>`: `assets/app-icon/<stem>-1024.png`,
//! `<stem>-macos-512.png` (with the margin macOS icons keep), `<stem>.ico`, `<stem>.icns` and the
//! `hicolor` PNG tree for Linux.

use std::collections::BTreeMap;
use std::path::Path;

use crate::art::{self, Canvas, Part};

/// Samples per pixel edge at the least (4×4 supersampling). Smaller sizes take more, so that
/// every pixel of the artwork under a pixel of the icon is counted.
const SS: u32 = 4;

type Rgba = [f32; 4];

fn rgb(hex: u32) -> Rgba {
    [((hex >> 16) & 255) as f32 / 255.0, ((hex >> 8) & 255) as f32 / 255.0, (hex & 255) as f32 / 255.0, 1.0]
}

/// Distance from a rounded rectangle's edge (negative inside); coordinates in the unit square.
fn round_rect(x: f32, y: f32, cx: f32, cy: f32, hw: f32, hh: f32, r: f32) -> f32 {
    let (dx, dy) = ((x - cx).abs() - (hw - r), (y - cy).abs() - (hh - r));
    dx.max(dy).min(0.0) + (dx.max(0.0).powi(2) + dy.max(0.0).powi(2)).sqrt() - r
}

/// The two colours every Craft icon shares; the third is the app's own.
const INK: u32 = 0x0B_0B_0C;
const PAPER: u32 = 0xEF_E9_DC;
/// The tile, in units of a 512 square: its corner radius, how far in the figure is clipped and
/// that clip's radius, and how much closer the small sizes show the figure.
const TILE_R: f32 = 112.0 / 512.0;
const INSET: f32 = 6.0 / 512.0;
const INSET_R: f32 = 106.0 / 512.0;
const SMALL_CROP: f32 = 22.0 / 512.0;
/// macOS icons sit on Apple's grid: an 824 px body on a 1024 px canvas.
const MAC_SCALE: f32 = 824.0 / 1024.0;
/// The artwork is drawn this many pixels a side.
const ART_SIDE: u32 = 4096;

/// One app's icon.
struct Icon {
    /// What its files are called.
    stem: &'static str,
    /// The reverse-DNS name its Linux icon files carry.
    app_id: &'static str,
    /// The app colour: the field.
    colour: u32,
    /// Draws its artwork.
    draw: fn(&mut Canvas) -> Result<(), String>,
}

const ICONS: [Icon; 2] = [
    Icon { stem: "screengrabcraft", app_id: "io.github.billsecond.screengrabcraft", colour: 0x0E_7C_7B, draw: art::falcon::draw },
    Icon { stem: "screengrabcraft-editor", app_id: "io.github.billsecond.screengrabcraft.editor", colour: 0x4E_3C_A8, draw: art::owl::draw },
];

/// An icon's artwork, drawn and snapped to its three parts.
struct Art {
    side: u32,
    parts: Vec<Part>,
}

impl Art {
    fn draw(icon: &Icon, side: u32) -> Result<Art, String> {
        let mut canvas = Canvas::new(side)?;
        (icon.draw)(&mut canvas)?;
        Ok(Art { side, parts: canvas.parts() })
    }

    /// The part at a point of the unit square.
    fn part(&self, u: f32, v: f32) -> Part {
        let pick = |t: f32| ((t.clamp(0.0, 1.0) * self.side as f32) as u32).min(self.side - 1);
        self.parts.get((pick(v) * self.side + pick(u)) as usize).copied().unwrap_or(Part::Field)
    }
}

/// The tile's colour at a point of the unit square, with the figure `crop` closer on each side.
fn tile(art: &Art, colour: u32, crop: f32, x: f32, y: f32) -> Rgba {
    if round_rect(x, y, 0.5, 0.5, 0.5, 0.5, TILE_R) > 0.0 {
        return [0.0; 4];
    }
    // The band of the app colour round the figure.
    if round_rect(x, y, 0.5, 0.5, 0.5 - INSET, 0.5 - INSET, INSET_R) > 0.0 {
        return rgb(colour);
    }
    let reach = 1.0 - 2.0 * crop;
    match art.part(crop + x * reach, crop + y * reach) {
        Part::Field => rgb(colour),
        Part::Paper => rgb(PAPER),
        Part::Ink => rgb(INK),
    }
}

/// The icon as `size`×`size` RGBA8 pixels, drawn inside `scale` of the canvas (1.0 fills it).
fn render(art: &Art, colour: u32, size: u32, scale: f32) -> Vec<u8> {
    let crop = if size <= 64 && scale >= 1.0 { SMALL_CROP } else { 0.0 };
    // Enough samples that every pixel of the artwork under a pixel of the icon is counted.
    let under = art.side as f32 * (1.0 - 2.0 * crop) / (size as f32 * scale);
    let n = (under.ceil() as u32).max(SS);
    render_with(size, scale, n, &|x, y| tile(art, colour, crop, x, y))
}

/// `sample` over the unit square as `size`×`size` RGBA8 pixels, inside `scale` of the canvas,
/// with `n`×`n` samples a pixel.
fn render_with(size: u32, scale: f32, n: u32, sample: &dyn Fn(f32, f32) -> Rgba) -> Vec<u8> {
    let mut out = Vec::with_capacity((size * size * 4) as usize);
    let count = (n * n) as f32;
    for py in 0..size {
        for px in 0..size {
            let mut acc = [0.0f32; 4];
            for sy in 0..n {
                for sx in 0..n {
                    let u = (px as f32 + (sx as f32 + 0.5) / n as f32) / size as f32;
                    let v = (py as f32 + (sy as f32 + 0.5) / n as f32) / size as f32;
                    // Shrink about the centre for icons that keep a margin.
                    let (u, v) = ((u - 0.5) / scale + 0.5, (v - 0.5) / scale + 0.5);
                    let s = if (0.0..=1.0).contains(&u) && (0.0..=1.0).contains(&v) { sample(u, v) } else { [0.0; 4] };
                    // Premultiplied while averaging, so edges don't darken.
                    acc[0] += s[0] * s[3];
                    acc[1] += s[1] * s[3];
                    acc[2] += s[2] * s[3];
                    acc[3] += s[3];
                }
            }
            let a = acc[3] / count;
            for ch in acc.iter().take(3) {
                out.push(if a > 0.0 { ((ch / count / a).clamp(0.0, 1.0) * 255.0).round() as u8 } else { 0 });
            }
            out.push((a.clamp(0.0, 1.0) * 255.0).round() as u8);
        }
    }
    out
}

fn png(art: &Art, colour: u32, size: u32, scale: f32) -> Result<Vec<u8>, String> {
    encode(size, render(art, colour, size, scale))
}

fn encode(size: u32, pixels: Vec<u8>) -> Result<Vec<u8>, String> {
    let img = image::RgbaImage::from_raw(size, size, pixels).ok_or("icon buffer has the wrong size")?;
    let mut bytes = std::io::Cursor::new(Vec::new());
    image::DynamicImage::ImageRgba8(img).write_to(&mut bytes, image::ImageFormat::Png).map_err(|e| format!("encoding the icon: {e}"))?;
    Ok(bytes.into_inner())
}

/// An Apple `.icns` holding PNG entries.
fn icns(entries: &[(&[u8; 4], Vec<u8>)]) -> Vec<u8> {
    let total: usize = 8 + entries.iter().map(|(_, d)| 8 + d.len()).sum::<usize>();
    let mut out = Vec::with_capacity(total);
    out.extend_from_slice(b"icns");
    out.extend_from_slice(&(total as u32).to_be_bytes());
    for (kind, data) in entries {
        out.extend_from_slice(*kind);
        out.extend_from_slice(&((8 + data.len()) as u32).to_be_bytes());
        out.extend_from_slice(data);
    }
    out
}

/// Writes one icon file, named from `assets/app-icon`.
type Write<'a> = &'a dyn Fn(&str, &[u8]) -> Result<(), String>;

/// Every file of one icon.
fn write_icon(icon: &Icon, art: &Art, write: Write<'_>) -> Result<(), String> {
    let (stem, colour) = (icon.stem, icon.colour);
    let mut plain = BTreeMap::new();
    for size in [16u32, 24, 32, 48, 64, 128, 256, 512, 1024] {
        plain.insert(size, png(art, colour, size, 1.0)?);
    }
    let mut mac = BTreeMap::new();
    for size in [16u32, 32, 64, 128, 256, 512, 1024] {
        mac.insert(size, png(art, colour, size, MAC_SCALE)?);
    }
    let get = |set: &BTreeMap<u32, Vec<u8>>, size: u32| set.get(&size).cloned().ok_or_else(|| format!("no {size} px icon"));
    for size in [16u32, 24, 32, 48, 64, 128, 256, 512] {
        write(&format!("hicolor/{size}x{size}/apps/{}.png", icon.app_id), &get(&plain, size)?)?;
    }
    write(&format!("{stem}-1024.png"), &get(&plain, 1024)?)?;
    write(&format!("{stem}-macos-512.png"), &get(&mac, 512)?)?;
    let ico = [16u32, 24, 32, 48, 64, 128, 256].into_iter().map(|size| get(&plain, size)).collect::<Result<Vec<_>, _>>()?;
    write(&format!("{stem}.ico"), &crate::ico::pack(&ico)?)?;
    let entries: Vec<(&[u8; 4], Vec<u8>)> = vec![
        (b"icp4", get(&mac, 16)?),
        (b"icp5", get(&mac, 32)?),
        (b"icp6", get(&mac, 64)?),
        (b"ic07", get(&mac, 128)?),
        (b"ic08", get(&mac, 256)?),
        (b"ic09", get(&mac, 512)?),
        (b"ic10", get(&mac, 1024)?),
        (b"ic11", get(&mac, 32)?),
        (b"ic12", get(&mac, 64)?),
        (b"ic13", get(&mac, 256)?),
        (b"ic14", get(&mac, 512)?),
    ];
    write(&format!("{stem}.icns"), &icns(&entries))?;
    Ok(())
}

pub fn run(root: &Path) -> Result<(), String> {
    let dir = root.join("assets/app-icon");
    let write = |rel: &str, bytes: &[u8]| -> Result<(), String> {
        let path = dir.join(rel);
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent).map_err(|e| format!("{}: {e}", parent.display()))?;
        }
        std::fs::write(&path, bytes).map_err(|e| format!("{}: {e}", path.display()))?;
        println!("wrote {}", path.display());
        Ok(())
    };
    for icon in &ICONS {
        let art = Art::draw(icon, ART_SIDE)?;
        println!("drew {} at {} px, app colour #{:06x}", icon.stem, art.side, icon.colour);
        write_icon(icon, &art, &write)?;
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    fn bytes(hex: u32) -> [u8; 3] {
        [(hex >> 16) as u8, (hex >> 8) as u8, hex as u8]
    }

    /// The colours of a render's opaque pixels, and how many of each.
    fn colours(px: &[u8]) -> BTreeMap<[u8; 3], usize> {
        let mut seen = BTreeMap::new();
        for p in px.as_chunks::<4>().0.iter().filter(|p| p[3] == 255) {
            *seen.entry([p[0], p[1], p[2]]).or_insert(0) += 1;
        }
        seen
    }

    #[test]
    fn each_icon_has_exactly_the_three_colours() {
        for icon in &ICONS {
            let art = Art::draw(icon, 1024).unwrap();
            for part in [Part::Field, Part::Paper, Part::Ink] {
                assert!(art.parts.contains(&part), "{}: the artwork has {part:?}", icon.stem);
            }
            let three: std::collections::BTreeSet<[u8; 3]> = [bytes(icon.colour), bytes(PAPER), bytes(INK)].into();
            // One sample a pixel: nothing but the three colours (and see-through corners).
            let sharp = render_with(64, 1.0, 1, &|x, y| tile(&art, icon.colour, SMALL_CROP, x, y));
            let seen: std::collections::BTreeSet<[u8; 3]> = colours(&sharp).into_keys().collect();
            assert_eq!(seen, three, "{}", icon.stem);
            // Smoothed, the three are still by far the commonest.
            let smooth = colours(&render(&art, icon.colour, 64, 1.0));
            let mut by_count: Vec<_> = smooth.into_iter().collect();
            by_count.sort_by_key(|(_, n)| std::cmp::Reverse(*n));
            let top: std::collections::BTreeSet<[u8; 3]> = by_count.iter().take(3).map(|(c, _)| *c).collect();
            assert_eq!(top, three, "{}", icon.stem);
        }
    }

    #[test]
    fn the_tile_frames_the_figure() {
        for icon in &ICONS {
            let art = Art::draw(icon, 512).unwrap();
            let colour = icon.colour;
            // Nothing where the tile's corner is cut away; the band round the figure is the app colour.
            assert_eq!(tile(&art, colour, 0.0, 0.01, 0.01)[3], 0.0);
            assert_eq!(tile(&art, colour, 0.0, 0.5, 0.004), rgb(colour));
            assert_eq!(tile(&art, colour, 0.0, 0.004, 0.5), rgb(colour));
            // The small sizes show the figure closer: the same point of it lands further out.
            let first_ink = |crop: f32| (0..400).find(|i| tile(&art, colour, crop, 0.5, *i as f32 / 400.0) == rgb(INK));
            let (near, far) = (first_ink(SMALL_CROP).unwrap(), first_ink(0.0).unwrap());
            assert!(near < far, "{}: {near} < {far}", icon.stem);
        }
    }

    #[test]
    fn renders_and_packs() {
        let art = Art::draw(&ICONS[0], 256).unwrap();
        let px = render(&art, ICONS[0].colour, 16, 1.0);
        assert_eq!(px.len(), 16 * 16 * 4);
        // The corner pixel is see-through, the middle isn't.
        assert_eq!(px[3], 0);
        assert_eq!(px[(8 * 16 + 8) * 4 + 3], 255);
        // The macOS render keeps its margin.
        let mac = render(&art, ICONS[0].colour, 64, MAC_SCALE);
        assert_eq!(mac[(32 * 64 + 2) * 4 + 3], 0);
        assert_eq!(mac[(32 * 64 + 32) * 4 + 3], 255);
        let data = png(&art, ICONS[0].colour, 32, 1.0).unwrap();
        assert_eq!(crate::ico::png_size(&data).unwrap(), (32, 32));
        let icns = icns(&[(b"icp5", data.clone())]);
        assert_eq!(&icns[..4], b"icns");
        assert_eq!(u32::from_be_bytes([icns[4], icns[5], icns[6], icns[7]]) as usize, icns.len());
        assert_eq!(icns.len(), 16 + data.len());
    }
}
